async function handleSignal(event,payload){if(event==='join'&&rtcRole==='host'&&rtcPeer?.localDescription){await broadcastSignal('offer',{description:rtcPeer.localDescription});rtcStatus('Friend found — waiting for connection…');}else if(event==='offer'&&rtcRole==='guest'){await rtcPeer.setRemoteDescription(payload.description);const answer=await rtcPeer.createAnswer();await rtcPeer.setLocalDescription(answer);await waitForIce(rtcPeer);await broadcastSignal('answer',{description:rtcPeer.localDescription});rtcStatus('Joining race…');}else if(event==='answer'&&rtcRole==='host'){await rtcPeer.setRemoteDescription(payload.description);rtcStatus('Answer received — connecting…');}}
function attachChannel(channel){rtcChannel=channel;channel.onopen=()=>{if(rtcConnectTimer)clearTimeout(rtcConnectTimer);rtcConnectTimer=null;rtcStatus('Connected — both players can start',true);els.opponent&&(els.opponent.textContent='Opponent: ready');sendRace({...roomStats(),type:'room-hello'});if(rtcSignalChannel)window.typeBoundSupabase.removeChannel(rtcSignalChannel).catch(()=>{});updateRoomPanel();};channel.onclose=()=>{rtcStatus('Connection closed');els.roomOpponentState.textContent='Disconnected';updateRoomPanel();};channel.onerror=()=>rtcStatus('Connection error');channel.onmessage=event=>{try{const data=JSON.parse(event.data);if(data.type==='room-hello'){els.roomOpponentName.textContent=data.name||'Anonymous typist';opponentRaceResult={name:data.name||'Anonymous typist',score:Number(data.score)||0,speed:Number(data.speed)||0,accuracy:Number(data.accuracy)||0,correct:Number(data.correct)||0,elapsed:Number(data.elapsed)||0,done:false};els.roomOpponentAvatar.textContent=(data.name||'?').slice(0,2).toUpperCase();els.roomOpponentSpeed.textContent=`${Number(data.speed||0).toFixed(1)} l/s`;els.roomOpponentAccuracy.textContent=`${Number(data.accuracy||0)}%`;els.roomOpponentState.textContent='Ready';els.roomOpponentState.classList.add('ready');els.roomFooterTitle.textContent='Both players ready';}if(data.type==='race-start'&&!state.active){if(modes[data.mode])setDifficulty(data.mode);els.roomOpponentState.textContent='Racing';els.roomOpponentState.classList.add('live');startGame(true);}if(data.type==='progress'){const speedValue=Number(data.speed)||0;els.opponent&&(els.opponent.textContent=data.done?'Opponent: finished':`Opponent: ${speedValue.toFixed(1)} l/s · ${Number(data.correct)||0} letters`);els.roomOpponentSpeed.textContent=`${speedValue.toFixed(1)} l/s`;els.roomOpponentAccuracy.textContent=`${Number(data.accuracy)||0}%`;els.roomOpponentProgress.textContent=data.done?'Finished':`${Number(data.correct)||0} letters · ${Number(data.score)||0} pts`;els.roomOpponentState.textContent=data.done?'Finished':'Racing';els.roomOpponentState.classList.add('live');opponentRaceResult={...(opponentRaceResult||{}),name:opponentRaceResult?.name||'Opponent',score:Number(data.score)||0,speed:speedValue,accuracy:Number(data.accuracy)||0,correct:Number(data.correct)||0,elapsed:Number(data.elapsed)||0,done:Boolean(data.done)};}if(data.type==='race-finish'){els.opponent&&(els.opponent.textContent=`Opponent finished · ${(Number(data.speed)||0).toFixed(1)} l/s`);els.roomOpponentProgress.textContent=`${Number(data.score)||0} pts · ${(Number(data.speed)||0).toFixed(1)} l/s`;els.roomOpponentState.textContent='Finished';opponentRaceResult={...(opponentRaceResult||{}),name:opponentRaceResult?.name||'Opponent',score:Number(data.score)||0,speed:Number(data.speed)||0,accuracy:Number(data.accuracy)||0,correct:Number(data.correct)||0,elapsed:Number(data.elapsed)||0,done:true};renderRaceComparison();}updateRoomPanel();}catch{rtcStatus('Received an invalid race update');}};}
function renderRaceComparison(){if(!els.raceComparison||!localRaceResult||!opponentRaceResult)return;const speedMode=mode().speedOnly||mode().custom,localValue=speedMode?localRaceResult.speed:localRaceResult.score,opponentValue=speedMode?opponentRaceResult.speed:opponentRaceResult.score,delta=localValue-opponentValue,winner=delta===0?'Tie race':delta>0?'You win':`${opponentRaceResult.name||'Opponent'} wins`;els.raceComparison.hidden=false;els.raceWinner.textContent=winner;els.raceOpponentName.textContent=opponentRaceResult.name||'Opponent';els.raceOpponentResult.textContent=speedMode?`${opponentValue.toFixed(1)} l/s · ${opponentRaceResult.accuracy}% accuracy`:`${Math.round(opponentValue).toLocaleString()} pts · ${opponentRaceResult.speed.toFixed(1)} l/s`;els.raceComparisonDelta.textContent=delta===0?'Equal result':`${delta>0?'+':''}${speedMode?delta.toFixed(1)+' l/s':Math.round(delta).toLocaleString()+(delta>0?' pts ahead':' pts behind')}`;}
function newPeer(){if(!window.RTCPeerConnection){rtcStatus('WebRTC is not supported in this browser');return null;}if(rtcPeer)rtcPeer.close();const configuredTurn=window.TYPE_BOUND_SUPABASE?.turn||{};const turnUrls=Array.isArray(configuredTurn.urls)?configuredTurn.urls.filter(Boolean):(configuredTurn.urls?[configuredTurn.urls]:[]);const iceServers=[{urls:['stun:stun.l.google.com:19302','stun:stun1.l.google.com:19302','stun:stun.cloudflare.com:3478']}];if(turnUrls.length&&configuredTurn.username&&configuredTurn.credential)iceServers.push({urls:turnUrls,username:configuredTurn.username,credential:configuredTurn.credential});rtcPeer=new RTCPeerConnection({iceServers,iceCandidatePoolSize:4});rtcPeer.onconnectionstatechange=()=>{const status=rtcPeer.connectionState;if(status==='connected')rtcStatus('Connected — both players can start',true);else if(['failed','disconnected','closed'].includes(status))rtcStatus(`Connection ${status} — try another network`);else rtcStatus(`Connecting… (${status})`);};rtcPeer.oniceconnectionstatechange=()=>{if(['failed','disconnected'].includes(rtcPeer.iceConnectionState))rtcStatus(`Network path ${rtcPeer.iceConnectionState} — check both networks`);};return rtcPeer;}
async function createOffer(){try{if(!window.typeBoundSupabase){rtcStatus('Connect Supabase Realtime to create rooms');return;}endRoom();const peer=newPeer();if(!peer)return;rtcRole='host';attachChannel(peer.createDataChannel('type-bound-race'));const token=roomToken();const offer=await peer.createOffer();await peer.setLocalDescription(offer);await waitForIce(peer);if(!await openSignalRoom(token,'host'))return;els.signalBox.value=roomInvite(token);await broadcastSignal('ready',{room:token});rtcStatus('Room ready — copy the invite link and send it');updateRoomPanel();}catch(error){rtcStatus(`Could not create a room: ${error?.message||'check browser permissions'}`);}}
async function applyOffer(){try{const token=roomFromInput();if(!validRoom(token))throw new Error('Enter a valid room invite or code.');endRoom();const peer=newPeer();if(!peer)return;rtcRole='guest';peer.ondatachannel=event=>attachChannel(event.channel);if(!await openSignalRoom(token,'guest'))return;els.signalBox.value=roomInvite(token);await broadcastSignal('join',{room:token});rtcStatus('Joining room…');if(rtcConnectTimer)clearTimeout(rtcConnectTimer);rtcConnectTimer=setTimeout(()=>{if(rtcChannel?.readyState!=='open'){rtcStatus('Could not connect — try another network or configure TURN');}},25000);updateRoomPanel();}catch(error){rtcStatus(error.message);}}
async function copySignal(){const value=els.signalBox.value.trim();if(!value)return rtcStatus('Create or join a room first.');try{await navigator.clipboard.writeText(value);rtcStatus('Invite copied');}catch{els.signalBox.focus();els.signalBox.select();rtcStatus('Select the invite and copy it manually');}}
function sendRace(message){if(rtcChannel?.readyState==='open'){const now=performance.now();if(message.type==='progress'&&now-lastRaceMessageAt<150)return;lastRaceMessageAt=now;rtcChannel.send(JSON.stringify(message));}}
function startGame(fromPeer=false) { if(!fromPeer){opponentRaceResult=null;localRaceResult=null;if(els.raceComparison)els.raceComparison.hidden=true;} if(mode().custom && (!els.customText.value.trim() || els.customText.value.trim().length<20)){ els.customText.focus(); els.hint.textContent='Paste at least 20 characters before starting custom practice.'; return; } clearInterval(timerId); state=freshState(); state.active=true; lastCountdown=-1; choosePhrase(); els.input.disabled=false; els.input.focus(); els.gameCard.classList.add('session-live'); document.body.classList.add('session-live'); els.start.textContent='Attack in progress'; els.start.disabled=true; els.modeFocusLabel.textContent='LIVE SESSION'; els.modeFocusTitle.textContent='Keep your rhythm'; els.status.textContent='LIVE'; els.dot.classList.add('live'); els.hint.textContent=mode().custom?'Type your paragraph exactly as written.':'Keep going — every correct letter builds your score.'; document.body.classList.add(`mode-${selectedMode}`); state.startedAt=performance.now(); timerId=setInterval(tick,50); updateStats(); beep('success'); if(!fromPeer)sendRace({type:'race-start',mode:selectedMode}); }
function tick() { state.elapsed=Math.min(mode().seconds,(performance.now()-state.startedAt)/1000); state.timeLeft=Math.max(0,mode().seconds-state.elapsed); const countdown=Math.ceil(state.timeLeft); if(countdown<=3&&countdown>0&&countdown!==lastCountdown){lastCountdown=countdown;beep('countdown');} sendRace({type:'progress',correct:state.correct,score:Math.round(state.score),speed:Number(speed().toFixed(1)),accuracy:Number(accuracy()),elapsed:Number(state.elapsed.toFixed(1)),done:false}); updateStats(); if(state.timeLeft<=0) finishGame(); }
function onType() { if(!state.active)return; const typed=els.input.value; const previous=state.currentTyped; state.currentTyped=typed.length; if(typed.length<previous)return; state.total+=typed.length-previous; const stats=getKeyStats(); for(let i=previous;i<typed.length;i++){ const expected=(state.currentPhrase[i]||' ').toLowerCase(); const actual=typed[i].toLowerCase(); const entry=stats[expected] ||= {attempts:0,correct:0,mistakes:{}}; entry.attempts++; const correct=typed[i]===state.currentPhrase[i]; if(correct){entry.correct++;state.correct++;state.combo++;state.bestCombo=Math.max(state.bestCombo,state.combo);if(!mode().speedOnly)state.score+=10*multiplier();beep('key');} else {entry.mistakes[actual]=(entry.mistakes[actual]||0)+1;state.combo=0;if(!mode().speedOnly)state.score=Math.max(0,state.score-5);beep('error');} } saveKeyStats(stats); scheduleAnalytics(stats); renderPhrase(); if(typed.length>=state.currentPhrase.length){if(!mode().speedOnly)state.score+=100*multiplier();state.combo+=3;beep('success');choosePhrase();} updateStats(); }
function finishGame() { if(!state.active)return; clearInterval(timerId);state.active=false;state.timeLeft=0;els.input.disabled=true;els.start.disabled=false;els.start.textContent='Start attack';els.modeFocusLabel.textContent='READY TO RUN';els.modeFocusTitle.textContent=mode().label;els.gameCard.classList.remove('session-live');document.body.classList.remove('session-live');els.status.textContent='COMPLETE';els.dot.classList.remove('live');els.hint.textContent='Run complete. See how you did.';sendRace({type:'race-finish',score:Math.round(state.score),speed:Number(speed().toFixed(1)),accuracy:Number(accuracy()),correct:state.correct,elapsed:Number(state.elapsed.toFixed(1)),done:true});const result=(mode().speedOnly||mode().custom)?speed():state.score;localRaceResult={name:localStorage.getItem(displayNameKey)||'You',score:Math.round(state.score),speed:Number(speed().toFixed(1)),accuracy:Number(accuracy()),correct:state.correct,elapsed:Number(state.elapsed.toFixed(1)),done:true};const oldBest=Number(localStorage.getItem(bestKey())||0),isBest=result>oldBest;if(isBest){localStorage.setItem(bestKey(),(mode().speedOnly||mode().custom)?result.toFixed(1):Math.round(result));els.best.textContent=(mode().speedOnly||mode().custom)?result.toFixed(1):Math.round(result).toLocaleString();}saveRun(result);if(selectedMode==='daily')updateDailyStreak();updateAchievements();els.resultMode.textContent=`${mode().label.toUpperCase()} · ${mode().seconds} SECONDS`;els.finalScore.textContent=(mode().speedOnly||mode().custom)?`${speed().toFixed(1)} l/s`:Math.round(state.score).toLocaleString();els.finalSpeed.innerHTML=`${speed().toFixed(1)} <small>l/s</small>`;els.finalAccuracy.textContent=`${accuracy()}%`;els.finalCombo.textContent=(mode().speedOnly||mode().custom)?'—':state.bestCombo;els.newBest.hidden=!isBest;els.raceComparison.hidden=true;renderRaceComparison();els.modal.hidden=false;els.gameCard.classList.remove('session-live');document.body.classList.remove('session-live');updateStats();beep('finish');}

function getHistory(){ try{return JSON.parse(localStorage.getItem(historyKey)||'[]');}catch{return [];} }
function getLeaderboard(){try{return JSON.parse(localStorage.getItem(leaderboardKey)||'[]');}catch{return [];}}
function leaderboardValue(entry){return entry.mode==='speed'||entry.mode==='custom'?entry.lps:entry.score;}
function getStreak(){try{return JSON.parse(localStorage.getItem(streakKey)||'{"current":0,"longest":0,"lastDate":""}');}catch{return {current:0,longest:0,lastDate:''};}}
function updateDailyStreak(){const today=new Date().toISOString().slice(0,10),streak=getStreak();if(streak.lastDate===today)return streak;const previous=new Date(`${streak.lastDate}T00:00:00Z`),current=new Date(`${today}T00:00:00Z`),days=streak.lastDate?Math.round((current-previous)/86400000):0;streak.current=days===1?streak.current+1:1;streak.longest=Math.max(streak.longest,streak.current);streak.lastDate=today;localStorage.setItem(streakKey,JSON.stringify(streak));return streak;}
function achievementStats(){const history=getHistory(),streak=getStreak();return {runs:history.length,bestScore:Math.max(0,...history.map(item=>item.score||0)),bestSpeed:Math.max(0,...history.map(item=>item.lps||0)),bestAccuracy:Math.max(0,...history.map(item=>item.accuracy||0)),dailyRuns:history.filter(item=>item.mode==='daily').length,longestStreak:streak.longest};}
function renderAchievements(){const stats=achievementStats(),unlocked=JSON.parse(localStorage.getItem(achievementKey)||'[]');els.achievementSummary.textContent=`${unlocked.length} of ${achievements.length} unlocked`;els.achievementGrid.innerHTML=achievements.map(item=>{const open=unlocked.includes(item.id);return `<article class="achievement-card ${open?'unlocked':'locked'}"><div class="badge-icon">${item.icon}</div><div><strong>${item.title}</strong><p>${item.description}</p><small>${open?'UNLOCKED':item.progress(stats)}</small></div></article>`;}).join('');}
function updateAchievements(){const stats=achievementStats(),unlocked=new Set(JSON.parse(localStorage.getItem(achievementKey)||'[]')),newUnlocks=[];achievements.forEach(item=>{if(!unlocked.has(item.id)&&item.test(stats)){unlocked.add(item.id);newUnlocks.push(item.title);}});localStorage.setItem(achievementKey,JSON.stringify([...unlocked]));renderAchievements();if(newUnlocks.length)toast(`Badge unlocked: ${newUnlocks.join(', ')}.`);}
function getKeyStats(){ if(keyStatsCache)return keyStatsCache; try{keyStatsCache=JSON.parse(localStorage.getItem(keyStatsKey)||'{}');}catch{keyStatsCache={};} return keyStatsCache; }
function saveKeyStats(stats){ keyStatsCache=stats; pendingKeyStats=stats; clearTimeout(statsSaveTimer); statsSaveTimer=setTimeout(()=>{if(pendingKeyStats)localStorage.setItem(keyStatsKey,JSON.stringify(pendingKeyStats));pendingKeyStats=null;},500); }
function scheduleAnalytics(stats){cancelAnimationFrame(analyticsFrame);analyticsFrame=requestAnimationFrame(()=>renderAnalytics(stats));}
function renderAnalytics(stats=getKeyStats()){ const rows=['qwertyuiop','asdfghjkl','zxcvbnm']; els.keyboard.innerHTML=rows.map(row=>`<div>${[...row].map(key=>{const item=stats[key],rate=item&&item.attempts?item.correct/item.attempts:1;return `<span class="key-cap ${rate<.75?'needs-work':rate<.9?'warm':''}" style="--accuracy:${rate*100}%" title="${key.toUpperCase()}: ${Math.round(rate*100)}% accuracy">${key.toUpperCase()}<small>${item?Math.round(rate*100)+'%':'—'}</small></span>`;}).join('')}</div>`).join(''); const mistakes=[];Object.entries(stats).forEach(([expected,item])=>Object.entries(item.mistakes||{}).forEach(([actual,count])=>mistakes.push({expected,actual,count})));mistakes.sort((a,b)=>b.count-a.count);els.mistakeList.innerHTML=mistakes.length?mistakes.slice(0,6).map(m=>`<li><b>${m.actual.toUpperCase()}</b> instead of <b>${m.expected.toUpperCase()}</b><span>${m.count}×</span></li>`).join(''):'<li>Keep typing to reveal your mistake patterns.</li>'; }
function setImagePreview(file){if(!file||!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)||file.size>2*1024*1024){toast('Avatar must be PNG, JPG, WEBP, or GIF under 2 MB.','error');return;}const reader=new FileReader();reader.onload=()=>{localStorage.setItem('type-bound-avatar',reader.result);els.avatar.src=reader.result;els.avatar.hidden=false;els.avatarPlaceholder.hidden=true;updateRoomPanel();};reader.readAsDataURL(file);}
function loadProfile(){const avatar=localStorage.getItem('type-bound-avatar'),name=localStorage.getItem(displayNameKey)||'Anonymous typist';if(avatar){els.avatar.src=avatar;els.avatar.hidden=false;els.avatarPlaceholder.hidden=true;}else{els.avatar.hidden=true;els.avatarPlaceholder.hidden=false;}els.profileName.textContent=name;if(els.displayNameInput)els.displayNameInput.value=name;}
async function saveDisplayName(){const value=(els.displayNameInput?.value||'').trim().replace(/\s+/g,' ');if(!/^[\p{L}0-9][\p{L}0-9 _-]{1,23}$/u.test(value)){toast('Use a display name 2–24 characters long.','error');return;}localStorage.setItem(displayNameKey,value);els.profileName.textContent=value;updateRoomPanel();if(rtcChannel?.readyState==='open')sendRace({...roomStats(),type:'room-hello'});if(window.typeBoundCloud?.isConfigured()){const result=await window.typeBoundCloud.saveProfileName(value);if(result?.error){toast('Saved on this device, but cloud save failed. Sign in and try again.','error');return;}toast('Display name saved locally and to Supabase.','success');return;}toast('Display name saved on this device. Sign in to sync it online.','success');}
function saveRun(result){ const run={mode:selectedMode,wpm:Math.round(speed()*12),lps:Number(speed().toFixed(1)),accuracy:Number(accuracy()),score:Math.round(result),time:Number(state.elapsed.toFixed(1)),at:new Date().toISOString()}; const history=getHistory();history.push(run);localStorage.setItem(historyKey,JSON.stringify(history.slice(-12)));const board=getLeaderboard();board.push(run);const ranked=Object.keys(modes).flatMap(modeKey=>board.filter(entry=>entry.mode===modeKey).sort((a,b)=>leaderboardValue(b)-leaderboardValue(a)).slice(0,5));localStorage.setItem(leaderboardKey,JSON.stringify(ranked));window.typeBoundCloud?.saveRun({mode:run.mode,score:run.score,lettersPerSecond:run.lps,accuracy:run.accuracy,duration:run.time,challengeDate:run.mode==='daily'?run.at.slice(0,10):null}).catch(()=>toast('Cloud sync failed, but your local score is safe.','error'));renderHistory();renderLeaderboard();renderProgressSummary(); }
function renderProgressSummary(){const history=getHistory(),streak=getStreak(),avg=history.length?history.reduce((sum,item)=>sum+Number(item.accuracy||0),0)/history.length:0;els.summarySpeed.textContent=Math.max(0,...history.map(item=>Number(item.lps||0))).toFixed(1);els.summaryAccuracy.textContent=avg?avg.toFixed(0):'0';els.summaryRuns.textContent=history.length;els.summaryStreak.textContent=streak.current;}
function renderHistory(){ const data=getHistory(); const canvas=els.chart,ctx=canvas.getContext('2d'),rect=canvas.getBoundingClientRect(),ratio=window.devicePixelRatio||1; canvas.width=Math.max(600,rect.width*ratio); canvas.height=300*ratio; ctx.scale(ratio,ratio); const width=Math.max(600,rect.width),height=300; ctx.clearRect(0,0,width,height); els.chartEmpty.hidden=data.length>0; if(!data.length)return; const max=Math.max(10,...data.map(d=>Math.max(d.wpm,d.lps*12))); const x=i=>data.length===1?width/2:34+i*(width-58)/(data.length-1); const y=v=>height-32-(v/max)*(height-60); ctx.strokeStyle=getComputedStyle(document.body).getPropertyValue('--line');ctx.lineWidth=1; for(let i=0;i<4;i++){const gy=height-32-i*(height-60)/3;ctx.beginPath();ctx.moveTo(28,gy);ctx.lineTo(width-10,gy);ctx.stroke();} [['wpm','--blue'],['lps','--verm']].forEach(([key,color])=>{ctx.beginPath();data.forEach((d,i)=>{const px=x(i),py=y(key==='lps'?d.lps*12:d[key]);i?ctx.lineTo(px,py):ctx.moveTo(px,py);});ctx.strokeStyle=getComputedStyle(document.body).getPropertyValue(color);ctx.lineWidth=3;ctx.stroke();data.forEach((d,i)=>{ctx.fillStyle=getComputedStyle(document.body).getPropertyValue(color);ctx.beginPath();ctx.arc(x(i),y(key==='lps'?d.lps*12:d[key]),4,0,Math.PI*2);ctx.fill();});}); }
function renderLeaderboard(){ const board=getLeaderboard(),rows=Object.entries(modes).flatMap(([key,item])=>board.filter(entry=>entry.mode===key).sort((a,b)=>leaderboardValue(b)-leaderboardValue(a)).slice(0,5).map((entry,index)=>`<div class="leader-row"><strong><i>#${index+1}</i> ${item.label}</strong><span>${key==='speed'||key==='custom'?entry.lps.toFixed(1)+' l/s':entry.score.toLocaleString()+' pts'}</span><small>${entry.accuracy}% · ${new Date(entry.at).toLocaleDateString()}</small></div>`)).join('');els.leaderboard.innerHTML=rows||'<div class="leader-empty">Finish a run to create your offline leaderboard.</div>';loadCloudLeaderboard(); }
async function loadCloudLeaderboard(){if(!window.typeBoundCloud?.isConfigured())return;const user=await window.typeBoundCloud.getUser();if(!user)return;const responses=await Promise.all(Object.keys(modes).map(key=>window.typeBoundCloud.getLeaderboard(key,5)));const cloudRows=responses.flatMap((response,index)=>{if(response.error)return [];const key=Object.keys(modes)[index],item=modes[key];return (response.data||[]).map((entry,rank)=>`<div class="leader-row"><strong><i>#${rank+1}</i> ${item.label}</strong><span>${key==='speed'||key==='custom'?Number(entry.letters_per_second).toFixed(1)+' l/s':Number(entry.score).toLocaleString()+' pts'}</span><small>${entry.accuracy}% · ${new Date(entry.created_at).toLocaleDateString()} · online</small></div>`);});if(cloudRows.length)els.leaderboard.innerHTML='<div class="cloud-leader-label">SIGNED-IN ONLINE SCORES</div>'+cloudRows.join('');}
function exportData(){ const best={}; Object.keys(modes).forEach(key=>{const recordKey=key==='daily'?`type-bound-best-daily-${new Date().toISOString().slice(0,10)}`:`type-bound-best-${key}`;const value=localStorage.getItem(recordKey);if(value!==null)best[key]=Number(value);}); const payload={app:'Type Bound',version:6,exportedAt:new Date().toISOString(),history:getHistory(),leaderboard:getLeaderboard(),best,keyStats:getKeyStats(),achievements:JSON.parse(localStorage.getItem(achievementKey)||'[]'),streak:getStreak(),profile:{avatar:localStorage.getItem('type-bound-avatar')||'',keypressSound:keypressSoundData,winSound:winSoundData},settings:{mode:selectedMode,soundOn,theme,soundPack,volumes}}; const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`type-bound-backup-${new Date().toISOString().slice(0,10)}.json`;link.click();URL.revokeObjectURL(url);toast('Backup exported successfully.'); }
function importData(file){ if(!file||file.size>2*1024*1024){toast('Backup files must be under 2 MB.','error');return;} const reader=new FileReader(); reader.onload=()=>{try{const payload=JSON.parse(reader.result);if(payload.app!=='Type Bound'||!Array.isArray(payload.history)||typeof payload.best!=='object')throw new Error('invalid'); localStorage.setItem(historyKey,JSON.stringify(payload.history.slice(-12)));if(Array.isArray(payload.leaderboard))localStorage.setItem(leaderboardKey,JSON.stringify(payload.leaderboard));if(payload.keyStats){keyStatsCache=payload.keyStats;localStorage.setItem(keyStatsKey,JSON.stringify(payload.keyStats));}if(payload.achievements)localStorage.setItem(achievementKey,JSON.stringify(payload.achievements));if(payload.streak)localStorage.setItem(streakKey,JSON.stringify(payload.streak));if(payload.settings?.soundPack){soundPack=payload.settings.soundPack;localStorage.setItem('type-bound-sound-pack',soundPack);}if(payload.settings?.volumes){volumes=payload.settings.volumes;localStorage.setItem('type-bound-volumes',JSON.stringify(volumes));}if(payload.profile?.avatar)localStorage.setItem('type-bound-avatar',payload.profile.avatar);if(payload.profile?.keypressSound){keypressSoundData=payload.profile.keypressSound;localStorage.setItem('type-bound-keypress-sound',keypressSoundData);}if(payload.profile?.winSound){winSoundData=payload.profile.winSound;localStorage.setItem('type-bound-win-sound',winSoundData);}Object.entries(payload.best).forEach(([key,value])=>{if(modes[key]&&Number.isFinite(Number(value))){const recordKey=key==='daily'?`type-bound-best-daily-${new Date().toISOString().slice(0,10)}`:`type-bound-best-${key}`;localStorage.setItem(recordKey,String(Number(value)));}});loadProfile();renderAnalytics();renderHistory();renderLeaderboard();renderAchievements();setDifficulty(selectedMode);syncMixer();toast('Backup restored successfully.');}catch{toast('That file is not a valid Type Bound backup.');}};reader.readAsText(file);}
function resetGame() { clearInterval(timerId);state=freshState();els.input.disabled=true;els.input.value='';els.phrase.textContent='Press start to begin your attack.';els.hint.textContent='Your first keystroke starts the timer.';els.round.textContent='ROUND 01';els.status.textContent='READY';els.dot.classList.remove('live');els.start.disabled=false;els.start.textContent='Start attack';updateStats(); }

