function updateFavicon(){if(!els.favicon)return;const colors=themeOptions[theme].colors;const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="${colors[0]}"/><path d="M16 17h19c10 0 15 5 15 12 0 5-3 8-7 10l9 9H39l-8-8h-5v8H16V17Zm10 9v7h8c4 0 6-1 6-4s-2-3-6-3h-8Z" fill="#fff"/><path d="M11 13h5v38h-5z" fill="${colors[1]}"/></svg>`;els.favicon.href=`data:image/svg+xml,${encodeURIComponent(svg)}`;}
function renderThemeMenu(){if(!els.themeMenu||!els.theme)return; els.themeMenu.innerHTML=Object.entries(themeOptions).map(([key,item])=>`<button class="theme-choice ${key===theme?'active':''}" data-theme-value="${key}" role="menuitem"><i style="background:linear-gradient(135deg,${item.colors[0]} 50%,${item.colors[1]} 50%)"></i><span>${item.label}</span></button>`).join('');const item=themeOptions[theme];els.theme.querySelector('b').textContent=item.label;els.theme.querySelector('.theme-swatch').style.background=`linear-gradient(135deg,${item.colors[0]} 50%,${item.colors[1]} 50%)`;updateFavicon();}
function setTheme(next){if(!themeOptions[next])return;theme=next;localStorage.setItem('type-bound-theme',theme);document.body.dataset.theme=theme;renderThemeMenu();updateRoomPanel();renderHistory();}
function setView(view){const valid=['home','progress','profile'];if(!valid.includes(view))view='home';document.body.classList.remove('home-view','progress-view','profile-view');document.body.classList.add(`${view}-view`);[els.playNav,els.progressNav,els.profileNav].forEach(button=>button?.classList.toggle('active',button.id===`${view}Nav`||view==='home'&&button.id==='playNav'));history.replaceState(null,'',view==='home'?'#home':`#${view}`);}
