function syncMixer(){els.soundPack.value=soundPack;els.masterVolume.value=volumes.master;els.uiVolume.value=volumes.ui;els.keyVolume.value=volumes.key;els.winVolume.value=volumes.win;}
els.soundPack.addEventListener('change',()=>{soundPack=els.soundPack.value;localStorage.setItem('type-bound-sound-pack',soundPack);beep('ui');});[['master',els.masterVolume],['ui',els.uiVolume],['key',els.keyVolume],['win',els.winVolume]].forEach(([name,input])=>input.addEventListener('input',()=>{volumes[name]=Number(input.value);localStorage.setItem('type-bound-volumes',JSON.stringify(volumes));}));
els.avatarFile.addEventListener('change',()=>{if(els.avatarFile.files[0])setImagePreview(els.avatarFile.files[0]);els.avatarFile.value='';}); function saveAudio(file,target,key,label){if(!file)return;if(!file.type.startsWith('audio/')||file.size>5*1024*1024){toast('Audio files must be under 5 MB.','error');return;}const reader=new FileReader();reader.onload=()=>{if(target==='key')keypressSoundData=reader.result;else winSoundData=reader.result;localStorage.setItem(key,reader.result);toast(`${label} saved locally.`);};reader.readAsDataURL(file);} els.keypressSoundFile.addEventListener('change',()=>{saveAudio(els.keypressSoundFile.files[0],'key','type-bound-keypress-sound','Custom keypress sound');els.keypressSoundFile.value='';}); els.winSoundFile.addEventListener('change',()=>{saveAudio(els.winSoundFile.files[0],'win','type-bound-win-sound','Custom winning alert');els.winSoundFile.value='';}); els.clearProfile.addEventListener('click',()=>{localStorage.removeItem('type-bound-avatar');localStorage.removeItem('type-bound-keypress-sound');localStorage.removeItem('type-bound-win-sound');keypressSoundData='';winSoundData='';loadProfile();toast('Local avatar and custom sounds cleared.');}); els.saveDisplayName?.addEventListener('click',saveDisplayName);els.displayNameInput?.addEventListener('keydown',event=>{if(event.key==='Enter')saveDisplayName();}); loadProfile(); updateRoomPanel(); renderAnalytics(); renderAchievements(); syncMixer();
function toast(message,type='info'){const item=document.createElement('div');item.className=`toast toast-${type}`;item.textContent=message;els.toastRegion.appendChild(item);requestAnimationFrame(()=>item.classList.add('show'));setTimeout(()=>{item.classList.remove('show');setTimeout(()=>item.remove(),220);},3600);}
function authError(message){els.authError.textContent=message;els.authError.hidden=false;els.authModal.querySelector('.auth-modal').classList.remove('shake');void els.authModal.offsetWidth;els.authModal.querySelector('.auth-modal').classList.add('shake');}
function clearAuthError(){els.authError.hidden=true;els.authError.textContent='';}
function setAuthMode(mode){const signup=mode==='signup';els.signInTab.classList.toggle('active',!signup);els.signUpTab.classList.toggle('active',signup);els.signIn.hidden=signup;els.signUp.hidden=!signup;els.authUsername.hidden=!signup;els.authUsernameLabel.hidden=!signup;els.authPassword.autocomplete=signup?'new-password':'current-password';els.authModeHint.textContent=signup?'Create an account to sync your progress across devices.':'Enter your email and password to continue.';clearAuthError();}
function openAuth(){if(window.typeBoundCloud?.isConfigured()){els.authModal.hidden=false;setAuthMode('signin');setTimeout(()=>els.authEmail.focus(),50);}else toast('Cloud sync is not configured yet. You can still play offline.','error');}
async function refreshCloudAccount(){if(!window.typeBoundCloud?.isConfigured()){els.authStatus.textContent='Offline mode — sign in is optional.';return;}try{const user=await window.typeBoundCloud.getUser();const signedIn=Boolean(user);let profileName=localStorage.getItem(displayNameKey)||'';if(signedIn){const profile=await window.typeBoundCloud.getProfile();profileName=profileName||profile?.data?.username||user?.user_metadata?.username||'';if(profileName){localStorage.setItem(displayNameKey,profileName);els.profileName.textContent=profileName;if(els.displayNameInput)els.displayNameInput.value=profileName;updateRoomPanel();if(rtcChannel?.readyState==='open')sendRace({...roomStats(),type:'room-hello'});}}els.openAuth.hidden=signedIn;els.signOut.hidden=!signedIn;els.authStatus.textContent=signedIn?`Signed in as ${user.email}.`:'Offline mode — sign in is optional.';if(signedIn){await window.typeBoundCloud.syncLocalHistory();loadCloudLeaderboard();}}catch{els.authStatus.textContent='Cloud unavailable — local mode is active.';}}
async function submitAuth(action){clearAuthError();const email=els.authEmail.value.trim(),password=els.authPassword.value,username=(els.authUsername?.value||'').trim();if(!email||!email.includes('@'))return authError('Enter a valid email address.');if(action==='signup'&&(!/^[\p{L}0-9][\p{L}0-9 _-]{1,23}$/u.test(username)))return authError('Use a display name 2–24 characters long.');if(password.length<6)return authError('Your password must be at least 6 characters.');const button=action==='signup'?els.signUp:els.signIn;button.disabled=true;button.classList.add('is-loading');button.dataset.label=button.textContent;button.textContent=action==='signup'?'Creating account…':'Signing in…';try{const result=action==='signup'?await window.typeBoundCloud.signUp(email,password,username):await window.typeBoundCloud.signIn(email,password);if(result.error){const message=result.error.message.includes('Invalid login')?'Email or password is incorrect.':result.error.message.includes('already registered')?'That email already has an account. Try signing in.':result.error.message;authError(message);return;}els.authModal.hidden=true;toast(action==='signup'?'Account created. Check your email if confirmation is enabled.':'Welcome back. Your scores are syncing.','success');await refreshCloudAccount();}catch{authError('Something went wrong. Check your connection and try again.');}finally{button.disabled=false;button.classList.remove('is-loading');button.textContent=button.dataset.label;}}
els.openAuth.addEventListener('click',openAuth);els.closeAuth.addEventListener('click',()=>els.authModal.hidden=true);els.authModal.addEventListener('click',event=>{if(event.target===els.authModal)els.authModal.hidden=true;});els.signInTab.addEventListener('click',()=>setAuthMode('signin'));els.signUpTab.addEventListener('click',()=>setAuthMode('signup'));els.signIn.addEventListener('click',()=>submitAuth('signin'));els.signUp.addEventListener('click',()=>submitAuth('signup'));els.togglePassword.addEventListener('click',()=>{const visible=els.authPassword.type==='text';els.authPassword.type=visible?'password':'text';els.togglePassword.textContent=visible?'Show':'Hide';els.togglePassword.setAttribute('aria-label',visible?'Show password':'Hide password');});els.authPassword.addEventListener('keydown',event=>{if(event.key==='Enter')submitAuth(els.signUp.hidden?'signin':'signup');});els.signOut.addEventListener('click',async()=>{try{await window.typeBoundCloud.signOut();toast('You are signed out. Local scores are still available.','info');await refreshCloudAccount();}catch{toast('Could not sign out. Please try again.','error');}});const inviteRoom=new URLSearchParams(location.search).get('room');if(inviteRoom&&validRoom(inviteRoom.toUpperCase())){els.signalBox.value=inviteRoom.toUpperCase();rtcStatus('Invite loaded — click Join race');}refreshCloudAccount();
